package com.ftk.tpip.control.application.catalog;import static org.junit.jupiter.api.Assertions.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.ftk.tpip.catalog.domain.model.*;import com.ftk.tpip.control.application.provider.CanonicalJsonService;import org.junit.jupiter.api.Test;
class CanonicalSchemaContentCanonicalizerTest{private final ObjectMapper m=new ObjectMapper();private final CanonicalSchemaContentCanonicalizer c=new CanonicalSchemaContentCanonicalizer(m,new CanonicalJsonService(m));@Test void canonicalizesSchemaAndProducesStableChecksum()throws Exception{var a=c.canonicalize(SchemaStandard.JSON_SCHEMA_2020_12,m.readTree("{\"properties\":{},\"type\":\"object\"}"),null,CompatibilityMode.BACKWARD);var b=c.canonicalize(SchemaStandard.JSON_SCHEMA_2020_12,m.readTree("{\"type\":\"object\",\"properties\":{}}"),null,CompatibilityMode.BACKWARD);assertEquals(a.checksum(),b.checksum());assertEquals("{\"properties\":{},\"type\":\"object\"}",a.schemaDocument());}@Test void rejectsUnsupportedDraft()throws Exception{assertThrows(IllegalArgumentException.class,()->c.canonicalize(SchemaStandard.JSON_SCHEMA_2020_12,m.readTree("{\"$schema\":\"http://json-schema.org/draft-07/schema#\"}"),null,CompatibilityMode.BACKWARD));}}
